from model import *
c=C(11,'下降规划与着陆计算详细设计','第二篇  分模块详细设计')
S(c,'TOD 几何模型',
P('高度、距离与角度的关系','''TODCalculator 将下降规划简化为高度差与水平距离之间的几何关系。from 和 to 以 ft 表示，距离以 NM 表示；给定路径角，可以由正切关系求距离，给定距离也可以求角度。高度差采用绝对值，因此几何距离保持非负。

这个模型不求解发动机推力、阻力、减速段或高度限制航点。其作用是在给定下降假设下估计距离或下降率，帮助理解页面显示。它与飞行管理计算机的完整垂直航迹预测有不同的输入规模和计算职责。

当前页面把输入及模式保存在 todCalculator 状态分区，服务类负责算术，Result 组件负责表达结果。切换输入模式不会改变公式的物理单位。''',diagram=D('formula','路径角和水平距离的几何关系',[['高度差','Δh = abs(from_ft − to_ft)'],['角度求距离','d_NM = Δh / tan(γ) × 0.000164579'],['距离求角度','γ = atan[Δh / (d_NM × 6076.12)] × 180 / π']]),table=T('量|单位|角色','当前及目标高度|ft|确定垂直距离\n路径角|degree|几何输入或输出\n距离|NM|水平距离\n地速|kt|时间及下降率换算')),
P('三度路径的数值示例','''从 35000 ft 下降至 3000 ft，高度差为 32000 ft。输入路径角 3°，距离为 32000/tan(3°)×0.000164579，约 100.49 NM。界面按其显示精度给出约 100 NM 的结果。

同一高度差下，角度越小，所需水平距离越长；角度越大，距离越短。该趋势来自几何关系，不含风场修正。角度模式的距离公式也不直接使用平均地速，地速只在进一步解释时间或下降率时起作用。

公式假设路径角恒定。实际需要平飞、减速或满足航点高度限制时，不能把单个几何距离当作完整下降程序。''',diagram=D('plot','32000 ft 高度差对应的几何下降距离',[],x=[2,2.5,3,3.5,4],series=[{'name':'距离 / NM','y':[150.815,120.625,100.49,86.095,75.314]}],xlabel='路径角 / degree',ylabel='NM'),table=T('角度|距离约值|解释','2°|150.8 NM|较缓路径\n3°|100.5 NM|本例输入\n4°|75.3 NM|较陡路径')),
P('下降率与时间表达','''给定垂直速度时，计算先用高度差除以垂直速度绝对值得到分钟数，再乘以平均地速每分钟对应的 NM 数。反向求垂直速度则先由距离和平均地速计算时间，再用 to−from 除以时间，保留下降的负号。

例如平均地速 400 kt、下降率大小 1600 ft/min、高度差 32000 ft，时间为 20 分钟，距离为 133.33 NM。若给定 100 NM，则时间为 15 分钟，平均垂直速度约 −2133.33 ft/min。

零下降率、零地速或相同高度会形成退化情况。服务类没有完整的领域错误返回类型，因此调用侧应先保证有效输入，不能把 Infinity 或 NaN 格式化为正常结果。''',diagram=D('formula','时间连接水平与垂直运动',[['已知垂直速度','t_min = Δh / abs(VS_ft/min)'],['水平距离','d_NM = averageGS_kt × t_min / 60'],['已知距离求垂直速度','VS = (to − from) / (d / averageGS × 60)']]),table=T('给定量|中间时间|结果','400 kt、1600 ft/min|20 min|133.33 NM\n400 kt、100 NM|15 min|−2133.33 ft/min\n路径角 3°|距离先由几何得到|不依赖地速求距离')) ,refs=['EFB','PERF'])
S(c,'分段地速与页面状态',
P('高度区间的构造','''地速输入为若干 {from, groundSpeed} 对象。服务类按 from 升序排列，把每一行的起始高度与下一行起始高度组成区间；最后一行延伸至一个足够大的上界。空值、零地速和空起始高度的记录被排除。

之后按当前与目标高度裁剪区间。最低和最高边界取两高度的最小值与最大值，首尾区间调整为恰好覆盖所需高度范围，中间区间保持原有边界。

这里的 from 是该地速段的高度起点，不是航班出发机场。字段含义依赖其模型上下文，接口文档中需要同时给出单位和对象类型。''',diagram=D('lanes','高度分段经过排序和裁剪',[['原始行','0 ft / 250 kt','10000 ft / 400 kt','更高高度行'],['排序后','建立下界','建立相邻区间','末段延伸'],['本次下降','裁剪至目标高度','保留中间段','裁剪至当前高度']]),table=T('原始行|形成的区间|本例裁剪','0 ft、250 kt|0～10000 ft|3000～10000 ft\n10000 ft、400 kt|10000 ft 以上|10000～35000 ft\n本例总范围|3000～35000 ft|32000 ft')),
P('高度加权平均地速','''findAverageGroundSpeed 用每段地速乘该段高度差，将这些乘积相加，再除以整个垂直范围。它采用高度区间权重，而不是时间权重，也不是简单对每行地速求算术平均。

在 3000～10000 ft 为 250 kt、10000～35000 ft 为 400 kt 的示例中，平均地速为 (250×7000+400×25000)/32000，即 367.1875 kt。直接平均两行会得到 325 kt，与实现不同。

这一简化适合当前工具的分段输入表达。若要模拟复杂风场或随时间变化的速度轨迹，应引入航段积分模型，不能仅把更多行输入视为已经完成时间积分。''',diagram=D('formula','源码采用的高度加权平均',[['区间权重','wi = hi_top − hi_bottom'],['平均地速','GSavg = Σ(GSi × wi) / Σwi'],['本例','GSavg = (250 × 7000 + 400 × 25000) / 32000']]),table=T('方法|本例结果|是否为当前实现','两行简单平均|325 kt|否\n高度加权平均|367.1875 kt|是\n时间加权平均|需时间轨迹|未在该服务实现')),
P('自动与手工输入模式','''TOD 状态分别保存地速模式、当前高度模式和计算输入模式。初始当前高度为手工模式，计算类型为路径角，输入值为 3；地速列表初始化为 0 ft 与 10000 ft 两行，地速数值仍需获得或填写。

自动模式表示从宿主读取相关数据，不代表从本地航班文件推导实时飞行状态。浏览器宿主只提供演示值，所以使用手工模式更容易复现书中的算例。切换模式时应查看页面上当前数值，而不是假定模式切换会自动形成完整可算数据。

setTodData 支持更新状态中的部分属性，地速行另有增加、删除和按索引修改动作。这种拆分使动态行表单与普通标量字段保持各自清晰的更新接口。''',diagram=D('entity','TOD 页面状态结构',[['模式','groundSpeedMode','currentAltitudeMode','calculationInputMode'],['高度与地速','currentAltitude','targetAltitude','groundSpeed[]'],['计算选择','calculation.type','calculation.input','Result 显示']],[(0,1,'决定值的来源'),(1,2,'输入服务类')]),table=T('状态变化|动作|影响','修改高度|setTodData|重新形成高度差\n新增地速段|addTodGroundSpeed|扩展分段列表\n删除地速段|removeTodGroundSpeed|移除指定行\n手动编辑行|setTodGroundSpeed|更新该段数值')) ,refs=['EFB','PERF'])
S(c,'着陆系数模型',
P('三维系数表与计算入口','''A330941LandingCalculator 通过跑道条件、自动刹车模式和襟翼构型三层索引选择 LandingData。每组数据包括基准距离及重量、速度、风、高度、温度、坡度、反推和超重程序修正系数。

公开方法接受一组着陆环境与构型输入，分别计算 MAX、MEDIUM、LOW 三种自动刹车距离。结果对象用三个有名称的字段返回，而不是依赖数组位置让页面猜测刹车模式。

该计算器是机型上下文注入的原生实现。它和本地起飞参考是两个不同模块，具有不同输入结构、资料来源及结果状态机制，不能混用起飞页的确认状态解释着陆页所有行为。''',diagram=D('tree','着陆资料的索引层次',['LandingData 系数选择',['跑道条件','干、湿及各等级','选择条件表'],['刹车模式','MAX / MEDIUM / LOW','选择制动组'],['襟翼构型','FULL / CONF 3','选择系数记录']]),table=T('结果字段|刹车模式|单位','maxAutobrakeDist|MAX|m\nmediumAutobrakeDist|MEDIUM|m\nlowAutobrakeDist|LOW|m\n共同输入|重量、构型、环境等|按接口单位')),
P('基准距离与加性修正','''私有计算方法先选择基准距离，再将各修正项相加。组合后的距离先 Math.round 取整，公开方法随后乘 1.15。这个顺序意味着最终结果仍可能含小数，不能描述成“全部计算完成后只取一次整数”。

干跑道、FULL 的基准距离分别为 1310、1670、2220 m。不同自动刹车模式具有各自系数，不只是对同一个 MAX 结果乘固定倍数。速度和风等变化时，三种模式间的比例也会变化。

修正项既可以为正，也可以为负，例如部分反推系数会减少距离。每项符号必须来自所选系数表，而非页面根据“开启”或“关闭”自行决定。''',diagram=D('formula','着陆距离的代码组合顺序',[['未加裕度距离','D0 = Dref + Σ各项修正'],['内部返回','D1 = round(D0)'],['公开结果','D = 1.15 × D1']]),table=T('干跑道 FULL|基准距离 / m|速度系数 / 每 5 kt','MAX|1310|80\nMEDIUM|1670|100\nLOW|2220|130')),
P('风、气温、坡度与反推','''顺风分量按相对跑道方向计算，负值即逆风被截为零，所以当前实现不因逆风给予距离减少。速度修正只取实际进近速度超过目标 VLS 的部分；低于目标的差值也截为零。

气压高度大于零才增加高度修正，气温高于按气压高度估算的 ISA 温度才增加温度修正。坡度为负时按下坡绝对值修正，上坡不获得相应减少。反推布尔值为真时采用两个反推器的系数，没有单侧数量输入。

这些条件说明算法的分段性。输入改变但结果不变，可能是处于零修正区间，而非界面没有更新。''',diagram=D('lanes','各修正项的启用条件',[['风与速度','只取顺风','只取超额速度','按 5 kt 比例'],['环境','正气压高度','高于 ISA','按高度及温差'],['构型','负坡度','双反推布尔值','超重及自动着陆']]),table=T('修正项|当前关系|零修正条件','顺风|tailwind / 5 × 系数|逆风或无风\n速度|超额速度 / 5 × 系数|不超过目标 VLS\n坡度|下坡百分数 × 系数|平坡或上坡\n反推|2 × 系数|未勾选反推')),
P('自动着陆与程序修正','''自动着陆修正按构型使用固定增量：FULL 为 180 m，CONF 3 为 160 m，然后一起进入最终裕度计算。超重程序则按所选 LandingData 的 overweightProcedureCorrection 加入，与简单比较某个重量阈值不是同一动作。

接口使用布尔字段表示是否采用这些程序，计算器不会从其他页面推断用户意图。页面输入应让用户知道这个勾选实际会增加哪一类修正，而不是用笼统的“高级选项”隐藏其作用。

系数表中不同模式的超重程序系数差异较大，因此报告比较不同刹车模式时应保留共同输入。只抄录三行距离，会失去理解结果所需的构型背景。''',diagram=D('components','构型标志进入加性修正',['襟翼 FULL / CONF 3','自动着陆标志','超重程序标志','所选 LandingData','修正合计','最终距离'],[(0,4,'确定自动着陆增量'),(1,4,'启用该增量'),(2,3,'启用程序系数'),(3,4,'系数值'),(4,5,'合计后加裕度')]),table=T('选项|FULL|CONF 3','自动着陆增量|180 m|160 m\n是否作用于最终裕度|是|是\n超重程序增量|由条件和刹车模式选表|由条件和刹车模式选表')) ,refs=['LAND','EFB','PERF'])
S(c,'着陆算例与资料解释',
P('VLS 目标与速度超额','''着陆计算器有独立的 FULL 与 CONF 3 VLS 数组。函数以 120 吨为起点、20 吨步长定位区间，并对质量上限做截断。190 吨 FULL 的上下节点为 180 吨 138 kt 和 200 吨 145 kt，插值得到 141.5 kt。

进近速度若输入 145 kt，则超额为 3.5 kt。干跑道 FULL、MAX 的速度修正为 3.5/5×80=56 m。这里的 VLS 目标仅用于该着陆公式，不能与起飞源码 V2 参考表互相替代。

原数组含九个值，而函数的上限 260 吨和 20 吨步长使最高索引通常为 7，代码中的 index===8 分支及数组注释存在不一致。这是该版本源码的资料解释问题，不能把注释当作已验证坐标。''',diagram=D('formula','190 吨 FULL 的速度修正',[['目标速度','VLS = 138 + (190 − 180) / 20 × (145 − 138)'],['速度超额','ΔV = max(145 − 141.5, 0) = 3.5 kt'],['MAX 修正','ΔDspeed = 3.5 / 5 × 80 = 56 m']]),table=T('速度对象|所属模型|本例','V2|本地起飞参考|与着陆无直接换用关系\nVLS|原生着陆目标|141.5 kt\n输入进近速度|用户条件|145 kt')),
P('隔离环境影响的计算示例','''为说明公式，取 190000 kg、干跑道、FULL、进近速度 145 kt、无风、海平面、QNH 1013.25 hPa、15°C、零坡度，反推、超重程序和自动着陆均关闭。重量差、环境及程序修正均为零，只保留速度修正。

MAX 为 round(1310+56)×1.15=1570.9 m；MEDIUM 为 round(1670+70)×1.15=2001 m；LOW 为 round(2220+91)×1.15=2657.65 m。该算例来自当前代码的算术，不是新增的飞机实测数据。

页面截图可能使用不同标高或其他输入，因此比较时须逐项对照条件。相近数值并不能证明输入完全一致。''',table=T('刹车模式|加裕度前 / m|函数结果 / m','MAX|1310 + 56 = 1366|1570.90\nMEDIUM|1670 + 70 = 1740|2001.00\nLOW|2220 + 91 = 2311|2657.65'),diagram=D('pipeline','本算例的计算路径',['190 t 与 FULL','VLS 141.5 kt','超额速度 3.5 kt','选择三组系数','各自距离取整','分别乘 1.15'])) ,
P('重量系数的量纲疑点','''LandingData 的注释把重量系数写为相对 190 吨“每 10 吨”的修正；实现却计算 weight/1000−190，并直接乘系数，没有再除以 10。以干跑道 FULL、MAX 的 170 为例，200 吨输入会得到 1700 m 的重量修正，而按注释理解会是 170 m。

本书描述现有实现，并明确区分源码运算与注释含义。仅凭两者不一致，无法确定应改代码还是改系数资料；需要回到对应原始性能资料、构型和单位定义才能修订。

因此当前着陆页面可用于软件流程和算法结构说明，不能据此声称性能数据已经过航空工程校准。这个限制集中来源于模型资料，和页面是否能够正常运行是不同问题。''',diagram=D('lanes','200 吨时两种量纲解释的差别',[['实际代码','200 − 190 = 10','10 × 170','1700 m'],['注释语义','(200 − 190) / 10','1 × 170','170 m']]),table=T('证据|可以确认|不能据此确认','源代码乘法|当前运行如何算|原始资料本来如何定义\n注释 per 10T|作者文字说明|注释一定比代码正确\n190 t 样例|零重量差算术|非基准重量校准正确')),
P('计算模块之间的复用边界','''TOD、着陆和本地起飞参考都使用高度、速度和质量，但模型假设不同。可以复用单位转换、字段格式化和图形控件，不应因为单位相同就共享一个未经说明的“性能结果”状态。

TOD 返回几何和运动学估计；着陆返回条件系数模型的三种距离；本地起飞返回带输入快照、版本和状态的参考对象。将三者作为明确的服务接口，有利于后续分别替换资料或算法。

扩展设计可以统一结果信封，加入 modelId、input、output、units、dataVersion 和 limitations，再由各模型定义具体输出。该结构不会自动消除现有资料疑点，只提供更清晰的追溯位置。''',diagram=D('entity','扩展设计：性能服务的共同结果信封',[['共同信封','modelId / version','input / units','limitations'],['模型输出','TOD 距离与率','着陆三种距离','起飞参考及状态'],['表现层','统一身份显示','按模型格式化','保留不同适用条件']],[(0,1,'承载模型专有输出'),(1,2,'显示明确语义')]),table=T('可以共用|应保持独立|原因','单位转换|模型适用性|规则不同\n输入控件|数据来源与版本|资料不同\n报告框架|结果字段|物理含义不同')) ,refs=['LAND','EFB','L-F'])

c=C(12,'航图、导航与资料浏览详细设计','第二篇  分模块详细设计')
S(c,'资料提供者与状态结构',
P('三个入口与一个查看器','''Navigation 组织 Navigraph、Local Files 和 Pinned Charts 三个入口。前两者是资料提供者，Pinned Charts 是已固定资料的索引视图。用户点击固定卡片后仍回到原提供者，收藏本身不成为第三套航图数据服务。

ChartViewer 集中处理缩放、平移、旋转、页码和全屏。提供者负责查找图件与得到可读资源，查看器负责显示和交互。这样不同资料源可以共享阅读体验，而不必各自实现一套缩放控件。

本地浏览器没有配置 Navigraph 账户授权或 SimBridge 文档服务。页面能够展示登录或连接状态，但交付包没有包含受订阅限制的航图库。''',diagram=D('components','航图提供者与查看器分离',['Navigraph 提供者','Local Files 提供者','Pinned Charts 索引','图件选择状态','ChartViewer','资源服务'],[(0,3,'选择在线图件'),(1,3,'选择本地图件'),(2,3,'恢复固定项'),(3,4,'统一显示'),(5,0,'授权资源'),(5,1,'文件服务')]),table=T('入口|数据性质|主要依赖','Navigraph|在线航图索引与图像|账户和服务授权\nLocal Files|本机资料服务中的文件|SimBridge Viewer\nPinned Charts|图件引用及元数据|原提供者仍可访问')),
P('提供者独立保存视图状态','''navigationTab 为 Navigraph 与 Local Files 各保存一份 ProviderTabInfo，包括搜索词、分类、图件身份、日夜资源链接、尺寸、页数、当前页、旋转角度、缩放比例和平移位置。这样切换提供者时不必丢失全部阅读上下文。

全局状态保存当前入口索引、提供者、主题、定位范围和固定图件列表。切换入口会清除 boundingBox，避免上一张地理配准图的范围继续用于另一资料源。

状态对象保存资源引用，并不意味着已经下载全部航图文件。资源可用性仍受原提供者连接和授权约束，视图恢复不能绕过这些条件。''',diagram=D('entity','航图状态的公共部分与提供者部分',[['公共状态','provider / selectedTab','theme / boundingBox','pinnedCharts[]'],['ProviderTabInfo','chartId / chartLinks','currentPage / rotation','position / scale'],['固定项','provider / chartId','title / tag','timeAccessed']],[(0,1,'选择当前视图'),(2,1,'恢复图件元数据')]),table=T('状态|保存目的|切换时的处理','chartPosition|恢复阅读位置|按提供者保存\nchartRotation|保留方向|固定项打开会重置\nboundingBox|定位图标换算|切换入口清除\nchartLinks|资源地址|重新加载资源')),
P('图件身份与资源地址','''chartId 标识图件，chartLinks 存放日间和夜间资源地址，chartName 与标题等用于列表和卡片显示。身份、显示名称、下载地址不应混用，因为同一图件的主题资源或临时访问地址可能变化。

查看器取得 Blob 后创建浏览器对象地址用于图像显示。资源加载与图像 onload 分属两个阶段；后者提供实际尺寸并结束加载状态。对用户而言，这两个阶段都应处于“尚未完成显示”的过程。

长期运行时，临时对象地址需要与图件生命周期配对释放。现有代码结构提示了这一资源管理位置；未来替换查看器或加强缓存时，应明确谁拥有 Blob 与 URL 的释放责任。''',diagram=D('sequence','资源身份到浏览器图像的形成',['图件选择','提供者 API','Blob / 对象地址','图像控件'],[(0,1,'chartId 与主题地址'),(1,2,'取得图像 Blob'),(2,3,'设置 src'),(3,0,'onload 回传尺寸')]),table=T('名称|含义|不宜替代的字段','chartId|图件身份|显示标题\nchartLinks|资源位置|永久资料身份\nBlob URL|当前浏览器资源引用|跨设备保存地址\nchartDimensions|实际显示尺寸|地理范围')) ,refs=['EFB','CHART','NAV'])
S(c,'查看器交互与地理定位',
P('缩放、平移与旋转','''ChartViewer 使用 TransformWrapper/TransformComponent 处理缩放和平移，初始变换来自 chartPosition。鼠标操作结束时把当前变换写回 Store，使后续页面渲染能够继续使用阅读位置。

旋转独立存入 chartRotation，左右旋转以 90° 为步长。旋转不是修改图像原文件，而是在显示容器上应用 CSS transform。图像内容、页码和数据来源保持原样。

缩放范围由查看器控制，当前设置为 0.05～5，且不严格限制在容器边界内。用户把图移出视野后，应通过适配或复位控件重新定位，而不是认为资源已经丢失。''',diagram=D('layers','图像显示的变换层次',['资源图像及原始尺寸','图件旋转容器：chartRotation','平移缩放容器：position 与 scale','阅读视口与工具栏']),table=T('交互|状态|作用','放大 / 缩小|scale|调整阅读尺度\n拖动|positionX / positionY|移动阅读位置\n旋转|chartRotation|改变显示方向\n复位 / 适配|组合变换|重新放入可见区域')),
P('多页 PDF 的页码状态','''本地 PDF 不由 ChartViewer 直接解析全部文档。getPdfUrl 通过 Viewer.getPDFPageUrl 请求某一页的可读资源，再把结果作为图像显示。pagesViewable 和 currentPage 控制翻页按钮及页码框。

翻页时资源请求可能失败，LocalFilesPage 的辅助函数使用加载提示和错误提示反馈。当前页码是逻辑选择，图像真正加载完成仍依赖资源返回与 onload；两者在错误状态下可能暂时不同步。

设计上应保持文件身份、页码与图像资源的一致绑定。后续并发优化时需要避免旧页请求晚返回覆盖新页，这属于请求顺序与显示状态之间的协调问题。''',diagram=D('sequence','本地 PDF 按页读取',['页码控件','getPdfUrl','Viewer 服务','ChartViewer'],[(0,1,'文件名与新页码'),(1,2,'getPDFPageUrl'),(2,1,'返回单页资源'),(1,3,'更新图像地址'),(3,3,'加载尺寸与图像')]),table=T('状态|含义|界面使用','pagesViewable|文档总页数|页码上限\ncurrentPage|当前选择页|翻页与输入框\nchartId|本地文件身份|单页请求参数\nloading|显示资源加载状态|加载提示')),
P('地理范围与飞机图标','''只有具备 boundingBox 的图件才有地理定位依据。查看器先判断飞机经纬度是否位于图件平面范围内，再按经纬度跨度与像素跨度做线性映射，得到图中位置。航向决定飞机符号的旋转方向。

纬度换算使用上界减当前纬度，因为屏幕纵坐标向下增加；经度则使用当前经度减左边界。这个方向差是地图坐标与屏幕坐标转换中的关键细节。

普通本地图像没有配准范围时，不能仅凭文件名或机场代码可靠地放置飞机图标。浏览器中的演示坐标也不代表已连接真实飞机位置。''',diagram=D('formula','经纬度向图件像素范围的映射',[['横向坐标','x = pixelWidth × (lon − lonMin) / (lonMax − lonMin)'],['纵向坐标','y = pixelHeight × (latMax − lat) / (latMax − latMin)'],['可见条件','lat、lon 均在 boundingBox 范围内']]),table=T('输入|来源|作用','经纬度|宿主位置变量|确定飞机位置\n真航向|宿主航向变量|旋转图标\n地理边界|图件配准数据|定义经纬度范围\n像素边界|图件配准数据|定义图像区域')),
P('主题与全屏阅读','''在线提供者可提供日间、夜间两套图像，usingDarkTheme 决定主题显示。它与 EFB 外壳主题不是完全相同的资源：外壳颜色变化不意味着图件本身已有夜间版本。图件身份和日夜链接需要一起保存。

全屏改变查看器在 EFB 内容区内的宽度，并保留退出入口。它不等同于浏览器 F11 全屏，后者由浏览器控制整个窗口。操作说明中分别称为“图件全屏”和“浏览器全屏”，避免混淆。

工具栏在放大状态下仍保持固定位置，便于恢复视野。对于较窄屏幕，宿主整体缩放会使控件一起变小，因此长时间阅读更适合较大的浏览器窗口。''',diagram=D('lanes','三种视觉层次各自作用',[['外壳主题','EFB 配色','菜单与控件','阅读背景'],['图件主题','日夜资源','相同图件身份','图面颜色'],['显示空间','图件全屏','浏览器窗口大小','最终可读尺寸']]),table=T('功能|控制范围|恢复方式','图件日夜|航图资源|再次切换主题\n图件全屏|EFB 内容区域|退出图件全屏\n浏览器全屏|浏览器窗口|浏览器快捷键\n宿主缩放|整张逻辑画布|扩大窗口')) ,refs=['EFB','CHART'])
S(c,'本地文件、固定图件与连接状态',
P('Local Files 的连接模型','''Local Files 使用 SimBridge 的 ClientState 判断连接。组件初始进入 ATTEMPTING；已有连接时进入 ESTABLISHED 并显示文件界面，否则短暂等待后显示 FAILED。重试按钮重新执行连接状态检查。

名称中的 Local Files 指由本机资料服务提供文件，并不是网页可以任意浏览操作系统磁盘。PDF 和图像都通过 Viewer API 获取。没有启动相应服务时出现连接失败，是该入口的依赖状态，而非 EFB 整体没有启动。

本交付不把本地航班 JSON 导入和航图本地文件入口合并。前者使用浏览器文件选择器读取业务输入，后者通过资料服务浏览图件，二者的权限和格式均不同。''',diagram=D('state','本地资料入口的连接状态',['ATTEMPTING','ESTABLISHED','FAILED','文件选择与查看'],[(0,1,'ClientState 已连接'),(0,2,'未连接'),(2,0,'用户重试'),(1,3,'显示资料界面')]),table=T('本地入口|使用方式|依赖','航班 JSON|浏览器选择文件|当前页面即可\n航图 Local Files|Viewer 资料 API|SimBridge 连接\nHTML 报告|浏览器下载及打开|无需航图服务')),
P('固定图件的引用模型','''PinnedChart 保存 provider、chartId、标题、副标题、标签、访问时间、页数、主题链接和可选地理范围。打开卡片时，把这些字段重新写入对应提供者视图，并重置旋转、当前页等显示状态，再更新访问时间。

列表支持按提供者和图件类型筛选，并提供访问时间和字母顺序等排序。标签颜色帮助识别 STAR、APP、TAXI、SID、REF；文字标签仍是主要语义，不依赖颜色单独表达类别。

删除固定项只移除引用卡片，不删除提供者的原始文件。这个区别应在操作手册中明确，使用户敢于整理收藏而不担心误删资料。''',diagram=D('entity','固定项保存可恢复的图件引用',[['PinnedChart','provider / chartId','title / subTitle / tag','timeAccessed'],['视图恢复','links / pages','boundingBox','入口索引'],['列表管理','筛选 / 搜索','排序','删除引用']],[(0,1,'打开卡片'),(0,2,'组织资料入口')]),table=T('动作|修改内容|原始图件','固定|新增引用元数据|保持\n打开|恢复视图并记录时间|从原来源读取\n排序|调整列表顺序|保持\n删除|移除固定引用|保持')),
P('资料失效与空状态表达','''航图模块可能出现未登录、服务未连接、没有搜索结果、未选择图件和资源加载失败等状态。这些状态分别属于身份、连接、检索、选择和读取阶段，不能统一显示为没有任何内容的空白区域。

当前查看器在缺少日夜链接时显示无图可显示；Local Files 提供失败与重试界面，Navigraph 提供认证入口。操作手册使用这些真实界面说明依赖，避免伪造已经取得航图的画面。

扩展缓存时，资料版本和授权范围必须随资源保存。收藏记录本身不能证明图件仍在有效期，也不能把之前成功显示过的资源认定为可永久离线分发。''',diagram=D('pipeline','航图显示的依赖链',['身份或本地服务','检索可用资料','选择图件','取得授权资源','图像加载完成','阅读与固定']),table=T('表现|所属阶段|合理解释','未登录|身份|完成服务授权后访问\n连接失败|资料服务|检查本机服务状态\n列表为空|检索|调整搜索或提供者\n无图显示|选择|尚无可用资源链接\n加载错误|资源读取|资源或网络请求失败')) ,refs=['EFB','CHART','NAV','AUTH'])
